import { useState, type ReactNode } from "react";
import { Link } from "react-router-dom";
import { AnimIcon, type IconName } from "@/components/art";
import { ErrorBoundary } from "@/components/ErrorBoundary";
import AIReasoning from "@/components/smoothui/ai-reasoning";
import { LiveTiles } from "@/components/LiveTiles";
import { RepoChat } from "@/components/RepoChat";
import { SolutionTabs } from "@/components/SolutionTabs";
import { Story } from "@/components/Story";
import { Terminal, type TermRow } from "@/components/Terminal";
import { AgentOrb, Eyebrow, Mark, Reveal, StatusBadge } from "@/components/ui-bits";
import type { RunDetail, Step } from "@/lib/api";
import { fixLabel, fmtDur, parsePatch, statusMeta, stepOk } from "@/lib/run";
import { cn, INSTALL_URL } from "@/lib/utils";
import { useLandingData, type LandingData } from "./landing-data";

/** The command that reproduces the featured run, as logged in the build log. */
const commandFor = (d: RunDetail | null) =>
  d ? `uv run python -m resurgo.run ${d.result.repo} ${d.result.sha}${d.result.path ? ` --path ${d.result.path}` : ""}` : null;

const stepRows = (steps: Step[], prefix: string): TermRow[] =>
  steps.map((s, i) => ({
    id: `${prefix}${i}`,
    kind: "step",
    label: s.name,
    command: s.command,
    ok: stepOk(s),
    duration: s.duration_s,
    lines: s.output_tail,
  }));

function CommandChip({ command }: { command: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <div className="flex max-w-full items-center gap-2 rounded-lg border border-border bg-terminal py-1.5 pl-4 pr-1.5 font-mono text-sm text-terminal-ink">
      <span aria-hidden className="text-muted-foreground">$</span>
      <code title={command} className="min-w-0 flex-1 truncate py-1">{command}</code>
      <button
        type="button"
        onClick={() => {
          navigator.clipboard?.writeText(command).then(() => {
            setCopied(true);
            setTimeout(() => setCopied(false), 1800);
          }).catch(() => undefined);
        }}
        className="press shrink-0 rounded-md border border-control px-3 py-1.5 text-xs font-semibold hover:bg-muted"
      >
        <span aria-live="polite">
          <span key={String(copied)} className="settle inline-block">{copied ? "✓ Copied" : "Copy"}</span>
        </span>
      </button>
    </div>
  );
}

/* 1. Hero ------------------------------------------------------------------ */
function Hero({ data }: { data: LandingData }) {
  const f = data.featured;
  const cmd = commandFor(f);
  return (
    <section className="mx-auto grid w-full max-w-7xl gap-14 px-4 pb-24 pt-16 sm:px-6 lg:grid-cols-[minmax(0,1fr)_minmax(0,1.05fr)] lg:pt-24">
      <div className="min-w-0">
        <Eyebrow>An agent that keeps projects runnable</Eyebrow>
        <h1 className="text-[clamp(3rem,7vw,5.75rem)] font-semibold leading-[0.95] tracking-[-0.03em]">
          Your projects, <Mark>runnable</Mark> again.
        </h1>
        <p className="mt-7 max-w-xl text-xl leading-relaxed text-muted-foreground">
          Resurgo fresh-clones your repos, repairs what rotted, and proves each fix in a clean container before it opens a pull request.
        </p>
        <div className="mt-9 flex flex-wrap items-center gap-3">
          <a
            href={INSTALL_URL}
            className="press inline-flex min-h-12 items-center rounded-lg border border-accent-strong bg-accent-strong px-6 text-base font-semibold text-on-accent hover:opacity-90"
          >
            Install on GitHub
          </a>
          <Link
            to="/runs"
            className="press inline-flex min-h-12 items-center rounded-lg border border-control px-5 text-base font-semibold hover:bg-muted"
          >
            See real runs
          </Link>
        </div>
        <p className="mt-4 max-w-xl text-sm text-muted-foreground">
          Pick the repos. Resurgo rebuilds each from a fresh clone and opens a pull request only for a fix that passes in a clean container.
        </p>
        {cmd && (
          <div className="mt-8 max-w-xl">
            <p className="mb-2 text-sm text-muted-foreground">or run it yourself (the run on the right):</p>
            <CommandChip command={cmd} />
          </div>
        )}
        <p className="mt-10 text-sm text-muted-foreground">
          Built on <span className="font-semibold text-foreground">neatlogs</span> tracing and{" "}
          <span className="font-semibold text-foreground">Entire</span> checkpoints.
        </p>
      </div>

      <div className="min-w-0 lg:pt-4">
        {f ? (
          <Story detail={f} loop label={`A real run of ${f.result.repo}, replayed`} />
        ) : data.loading ? (
          <p className="text-muted-foreground" role="status">◌ Loading a recorded run…</p>
        ) : null}
      </div>
    </section>
  );
}

/* 3. Three steps, as story rows -------------------------------------------- */
function Steps({ data }: { data: LandingData }) {
  const f = data.featured;
  if (!f) return null;
  const a = f.result.agent;
  const clone = (a?.steps ?? []).filter((s) => s.name === "clone" || s.name === "detect").slice(0, 2);
  const attempts = a?.attempts ?? [];
  const proof = f.result.verifier?.steps ?? [];
  const items: { icon: IconName; title: string; body: string; rows: TermRow[] }[] = [
    {
      icon: "check" as const,
      title: "A fresh clone, every time",
      body: "No cached node_modules, no warm machine. If it only works on your laptop, this is where it stops working.",
      rows: stepRows(clone, "c"),
    },
    {
      icon: "repair" as const,
      title: "The least invasive fix first",
      body: "Version pins and config before anything else. Source code is only ever proposed, and waits for your approval.",
      rows: attempts.map((x, i) => ({
        id: `a${i}`,
        kind: "step" as const,
        label: `repair ${i + 1}`,
        command: `${x.kind} · ${(x.files ?? []).join(", ")}`,
        ok: x.result === "passed",
        lines: [x.result ?? ""],
      })),
    },
    {
      icon: "prove" as const,
      title: "Proof in a clean container",
      body: "A second container, built from the recipe alone, has to pass. The agent that wrote the fix cannot write to it.",
      rows: stepRows(proof, "p"),
    },
  ].filter((i) => i.rows.length > 0);
  return (
    <section className="mx-auto max-w-7xl space-y-24 px-4 py-28 sm:px-6">
      {items.map((it, i) => (
        <div key={it.title} className="grid grid-cols-1 items-center gap-10 lg:grid-cols-2">
          <Reveal className={cn(i % 2 && "lg:order-2")}>
            <AnimIcon name={it.icon} className="size-9 text-accent-strong" />
            <h2 className="mt-5 text-4xl font-semibold tracking-tight sm:text-5xl">{it.title}</h2>
            <p className="mt-4 max-w-md text-lg text-muted-foreground">{it.body}</p>
          </Reveal>
          <Reveal delay={0.15} x={i % 2 ? -24 : 24}>
            <Terminal title={`${f.result.repo} · ${it.title.toLowerCase()}`} rows={it.rows} compact tailLines={4} />
          </Reveal>
        </div>
      ))}
    </section>
  );
}

/* 4. Your projects --------------------------------------------------------- */
function Projects({ data }: { data: LandingData }) {
  const f = data.featured;
  if (!data.latest.length) return null;
  const a = f?.result.agent?.attempts?.[f.result.agent.attempts.length - 1];
  return (
    <section className="border-y border-border bg-panel/50">
      <div className="mx-auto grid max-w-7xl gap-10 px-4 py-24 sm:px-6 lg:grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)]">
        <Reveal className="min-w-0">
          <Eyebrow>Your projects</Eyebrow>
          <h2 className="text-4xl font-semibold tracking-tight sm:text-5xl">One state per project, in words.</h2>
          <ul className="mt-8 divide-y divide-border rounded-lg border border-border bg-panel" role="list">
            {data.latest.map((r) => (
              <li key={r.id}>
                <Link to={`/runs/${r.id}`} className="flex flex-wrap items-center gap-x-4 gap-y-1 px-4 py-3 hover:bg-muted">
                  <span className="min-w-0 flex-1 truncate font-semibold">
                    {r.repo}{r.path ? <span className="font-normal text-muted-foreground">/{r.path}</span> : null}
                  </span>
                  <span className="font-mono text-sm tabular-nums text-muted-foreground">{fmtDur(r.duration_s)}</span>
                  <StatusBadge status={r.status} />
                </Link>
              </li>
            ))}
          </ul>
          <p className="mt-3 text-sm text-muted-foreground">Latest run per repository, straight from the run records.</p>
        </Reveal>
        {a?.rationale && (
          <Reveal delay={0.15} className="min-w-0">
            <div className="flex items-center gap-4">
              <AgentOrb thinking={false} size={72} />
              <div>
                <h3 className="text-xl font-semibold">What the agent concluded</h3>
                <p className="text-sm text-muted-foreground">From {f?.result.repo}</p>
              </div>
            </div>
            <div className="mt-5 rounded-lg border border-border bg-panel p-4">
              <AIReasoning defaultOpen collapseWhenDone={false} duration={(f?.result.model_calls ?? []).reduce((s, c) => s + (c.duration_s ?? 0), 0) || undefined}>
                <p className="text-foreground">{a.rationale}</p>
                {a.confidence != null && <p className="mt-2 font-mono text-xs">confidence {a.confidence}</p>}
              </AIReasoning>
            </div>
          </Reveal>
        )}
      </div>
    </section>
  );
}

/* 5. Open a run ------------------------------------------------------------ */
function OpenARun({ data }: { data: LandingData }) {
  // Everything here comes from the /api/runs summaries: no per-run fetch.
  const cards = [...data.latest].sort((a, b) => Number(!!b.patch_preview) - Number(!!a.patch_preview)).slice(0, 3);
  if (!cards.length) return null;
  return (
    <section className="mx-auto max-w-7xl px-4 py-28 sm:px-6">
      <Reveal>
        <h2 className="max-w-3xl text-4xl font-semibold tracking-tight sm:text-6xl">Don&apos;t take our word for it. Open a run.</h2>
      </Reveal>
      <div className="mt-12 grid grid-cols-1 gap-6 lg:grid-cols-3">
        {cards.map((r, i) => {
          const file = r.patch_preview ? parsePatch(r.patch_preview)[0] : null;
          return (
            <Reveal key={r.id} delay={i * 0.1}>
              <Link to={`/runs/${r.id}`} className="group flex h-full flex-col rounded-xl border border-border bg-panel p-5 transition-colors hover:border-accent-strong">
                <StatusBadge status={r.status} className="self-start" />
                <h3 className="mt-4 break-words text-2xl font-semibold">{r.repo}</h3>
                <p className="mt-1 text-sm text-muted-foreground">
                  {fixLabel(r.fix_kind, r.needs_approval)} fix · {fmtDur(r.duration_s)} · {r.model_calls} model call{r.model_calls === 1 ? "" : "s"}
                </p>
                {file ? (
                  <pre className="mt-5 flex-1 overflow-hidden rounded-md border border-border bg-terminal p-3 font-mono text-xs leading-relaxed text-terminal-ink">
                    <span className="text-muted-foreground">{file.title}</span>
                    {file.lines.slice(0, 7).map((l, j) => (
                      <span key={j} className={cn("block whitespace-pre", l.kind === "added" && "bg-evidence text-on-evidence")}>
                        {l.kind === "added" ? "+" : l.kind === "removed" ? "-" : " "}{l.content}
                      </span>
                    ))}
                  </pre>
                ) : (
                  <p className="mt-5 flex-1 text-sm text-muted-foreground">
                    {r.fix_kind ? "Open the run to read the patch." : "No fix was recorded for this run."}
                  </p>
                )}
                <p className="mt-5 text-sm font-semibold underline-offset-4 group-hover:underline">Open the run →</p>
              </Link>
            </Reveal>
          );
        })}
      </div>
    </section>
  );
}

/* 6. The problem ----------------------------------------------------------- */
function Problem({ data }: { data: LandingData }) {
  if (!data.problems.length) return null;
  return (
    <section className="border-y border-border bg-panel/50">
      <div className="mx-auto max-w-7xl px-4 py-28 sm:px-6">
        <Reveal>
          <h2 className="max-w-4xl text-4xl font-semibold tracking-tight sm:text-6xl">Projects rot while you&apos;re not looking.</h2>
          <p className="mt-5 max-w-2xl text-lg text-muted-foreground">Nothing in the repository changed. These are the real causes we recorded.</p>
        </Reveal>
        <ol className="mt-14 grid grid-cols-1 gap-px overflow-hidden rounded-xl border border-border bg-border lg:grid-cols-3" role="list">
          {data.problems.map((p, i) => (
            <li key={p.key} className="bg-canvas">
              <Reveal delay={i * 0.12} className="flex h-full flex-col p-6">
                <span className="font-mono text-sm text-muted-foreground">0{i + 1}</span>
                <h3 className="mt-3 text-2xl font-semibold">{p.title}</h3>
                <p className="mt-3 text-muted-foreground">{p.body}</p>
                <blockquote className="mt-6 flex-1 whitespace-pre-wrap break-words border-l-2 border-evidence pl-4 font-mono text-xs leading-relaxed">
                  {p.evidence.length > 380 ? `${p.evidence.slice(0, 380)}…` : p.evidence}
                </blockquote>
                <Link to={`/runs/${p.runId}`} className="mt-5 text-sm text-muted-foreground underline underline-offset-4 hover:text-foreground">
                  Recorded in {p.source}
                </Link>
              </Reveal>
            </li>
          ))}
        </ol>
      </div>
    </section>
  );
}

/* 7. The solution: tabs ---------------------------------------------------- */
function Solution({ data }: { data: LandingData }) {
  const f = data.featured;
  if (!f) return null;
  const st = data.stats;
  return (
    <section className="mx-auto max-w-7xl px-4 py-28 sm:px-6">
      <Reveal>
        <Eyebrow>How it works</Eyebrow>
        <h2 className="max-w-3xl text-4xl font-semibold tracking-tight sm:text-6xl">Check. Diagnose. Repair. Prove.</h2>
      </Reveal>
      <SolutionTabs detail={f} />

      {st && (
        <Reveal className="mt-16">
          <dl className="grid gap-px overflow-hidden rounded-xl border border-border bg-border sm:grid-cols-3">
            {[
              { k: "Runs recorded", v: String(st.recorded) },
              { k: "Verified in a clean container", v: String(st.verified) },
              ...(st.medianVerifiedS != null ? [{ k: "Median wall time of a verified fix", v: fmtDur(st.medianVerifiedS) }] : []),
            ].map((s) => (
              <div key={s.k} className="bg-canvas p-6">
                <dd className="font-mono text-5xl font-semibold tabular-nums tracking-tight">{s.v}</dd>
                <dt className="mt-2 text-muted-foreground">{s.k}</dt>
              </div>
            ))}
          </dl>
          <p className="mt-3 text-sm text-muted-foreground">
            Counted from the recorded development-repo runs above. These are not the held-out evaluation.
          </p>
        </Reveal>
      )}
    </section>
  );
}

/* 9. Developer surface ----------------------------------------------------- */
function Artifacts({ data }: { data: LandingData }) {
  const f = data.featured;
  if (!f) return null;
  const r = f.result;
  const record = JSON.stringify(
    { run_id: r.run_id, repo: r.repo, sha: r.sha, type: r.type, agent_version: r.agent_version, needs_approval: r.needs_approval, fixed: r.fixed, result: r.result },
    null,
    2,
  );
  const proof = JSON.stringify(
    (r.verifier?.steps ?? []).map((s) => ({ name: s.name, exit_code: s.exit_code, duration_s: s.duration_s })),
    null,
    2,
  );
  const cards: { title: string; body: string; code: string }[] = [
    { title: "Reproduce it", body: "One command re-runs the check from a fresh clone.", code: commandFor(f) ?? "" },
    { title: "The run record", body: "Every run writes one JSON file. This is the real one, trimmed.", code: record },
    ...(f.fix_patch ? [{ title: "The patch", body: "The fix, as a plain unified diff you can read before it merges.", code: f.fix_patch.trim() }] : []),
    ...(proof !== "[]" ? [{ title: "The proof", body: "What the separate clean container ran, and how each step ended.", code: proof }] : []),
  ];
  return (
    <section className="border-y border-border bg-panel/50">
      <div className="mx-auto max-w-7xl px-4 py-28 sm:px-6">
        <Reveal>
          <h2 className="max-w-3xl text-4xl font-semibold tracking-tight sm:text-6xl">Everything it does is a file you can read.</h2>
          <p className="mt-4 text-muted-foreground">
            Agents can read it too: <a href="/index.md" className="font-semibold text-accent-strong underline underline-offset-4">the Agent view</a> describes the API and how runs are proved.
          </p>
        </Reveal>
        <div className="mt-12 grid grid-cols-1 gap-6 md:grid-cols-2">
          {cards.map((c, i) => (
            <Reveal key={c.title} delay={(i % 2) * 0.1}>
              <div className="flex h-full flex-col rounded-xl border border-border bg-canvas p-5">
                <h3 className="text-xl font-semibold">{c.title}</h3>
                <p className="mt-1 text-muted-foreground">{c.body}</p>
                <pre className="mt-4 max-h-64 flex-1 overflow-auto rounded-md border border-border bg-terminal p-3 font-mono text-xs leading-relaxed text-terminal-ink" tabIndex={0}>
                  {c.code}
                </pre>
              </div>
            </Reveal>
          ))}
        </div>
      </div>
    </section>
  );
}

/* 10. Toolchains ----------------------------------------------------------- */
function Toolchains() {
  const names = ["Node", "pnpm", "npm", "Yarn", "Foundry", "Cargo", "Docker", "GitHub"];
  return (
    <section className="mx-auto max-w-7xl px-4 py-16 sm:px-6" aria-label="Toolchains">
      <p className="text-sm text-muted-foreground">What the runner is built to handle</p>
      <ul className="mt-4 flex flex-wrap gap-x-8 gap-y-2 text-2xl font-semibold" role="list">
        {names.map((n) => <li key={n}>{n}</li>)}
      </ul>
    </section>
  );
}

/* 11. Final CTA ------------------------------------------------------------ */
function Closing({ data }: { data: LandingData }) {
  const history = [...data.runs].filter((r) => r.status !== "checking").reverse();
  const tone = (s: string) => {
    const m = statusMeta(s);
    return m.text === "text-runs" ? "bg-runs text-canvas" : m.text === "text-broken" ? "bg-broken text-canvas" : "bg-gaps text-canvas";
  };
  const steps = ["Install the app", "Pick repos", "First check", "Weekly re-checks"];
  return (
    <section className="mx-auto max-w-7xl px-4 py-28 sm:px-6">
      <Reveal>
        <h2 className="max-w-4xl text-5xl font-semibold leading-[1.02] tracking-tight sm:text-7xl">Connect once. Resurgo keeps watch.</h2>
        <p className="mt-6 max-w-2xl text-lg text-muted-foreground">
          The GitHub App is the next thing to build. Until it ships, every run on this site is a real one, run by hand.
        </p>
      </Reveal>

      {history.length > 0 && (
        <Reveal className="mt-14">
          <p className="mb-3 text-sm text-muted-foreground">
            Every run so far, oldest to newest ({history.length}). Open any bar.
          </p>
          <ol className="flex h-20 gap-1" role="list">
            {history.map((r) => (
              <li key={r.id} className="flex-1">
                <Link
                  to={`/runs/${r.id}`}
                  title={`${r.repo} · ${statusMeta(r.status).word}`}
                  className={cn("flex h-full min-w-2 items-start justify-center rounded-sm pt-1.5 text-sm font-bold hover:opacity-80", tone(r.status))}
                >
                  <span aria-hidden>{statusMeta(r.status).glyph}</span>
                  <span className="sr-only">{r.repo}: {statusMeta(r.status).word}</span>
                </Link>
              </li>
            ))}
          </ol>
          <p className="mt-3 flex flex-wrap gap-x-5 font-mono text-xs text-muted-foreground">
            <span>✓ Runs</span><span>◐ Runs with gaps or fixed, unverified</span><span>✗ Broken</span>
          </p>
        </Reveal>
      )}

      <Reveal className="mt-16">
        <p className="mb-4 font-mono text-xs uppercase tracking-[0.18em] text-muted-foreground">Planned flow</p>
        <ol className="grid gap-px overflow-hidden rounded-xl border border-border bg-border sm:grid-cols-4" role="list">
          {steps.map((s, i) => (
            <li key={s} className="bg-canvas p-5">
              <span className="font-mono text-sm text-muted-foreground">0{i + 1}</span>
              <p className="mt-2 text-lg font-semibold">{s}</p>
            </li>
          ))}
        </ol>
        <p className="mt-4 text-muted-foreground">
          Planned pricing: about $2 per verified fix, and checks free for up to 10 repositories. That is an intended charge, not a measured one.
        </p>
      </Reveal>
    </section>
  );
}

const Safe = ({ label, children }: { label: string; children: ReactNode }) => (
  <ErrorBoundary label={label}>{children}</ErrorBoundary>
);

export default function Landing() {
  const data = useLandingData();
  return (
    <main>
      <Safe label="The hero"><Hero data={data} /></Safe>
      <Safe label="The repository tiles"><LiveTiles runs={data.latest} /></Safe>
      <Safe label="The repository chat"><RepoChat latest={data.latest} /></Safe>
      <Safe label="The three steps"><Steps data={data} /></Safe>
      <Safe label="The project list"><Projects data={data} /></Safe>
      <Safe label="The run gallery"><OpenARun data={data} /></Safe>
      <Safe label="The problem section"><Problem data={data} /></Safe>
      <Safe label="The solution section"><Solution data={data} /></Safe>
      <Safe label="The run artifacts"><Artifacts data={data} /></Safe>
      <Toolchains />
      <Safe label="The run history"><Closing data={data} /></Safe>
    </main>
  );
}

"""Read-only public gallery API over the run records in RUNS_DIR, plus the built web app."""

import json
import os
import re
import time
from pathlib import Path

from fastapi import FastAPI, HTTPException
from fastapi.responses import FileResponse, PlainTextResponse

RUNS_DIR = Path(os.environ.get("RUNS_DIR", "")).resolve() if os.environ.get("RUNS_DIR") else None
DIST_DIR = Path(os.environ.get("WEB_DIST", Path(__file__).resolve().parent.parent / "web" / "dist")).resolve()

# 20261010T120139Z-5c3370f: UTC timestamp, then a short sha. Nothing else is ever a run id.
RUN_ID = re.compile(r"^[0-9]{8}T[0-9]{6}Z-[0-9a-f]{6,40}$")
# A run directory with no result.json younger than this is still being checked.
CHECKING_WINDOW_S = 45 * 60

app = FastAPI(title="Resurgo runs", docs_url=None, redoc_url=None, openapi_url=None)


def _runs_dir() -> Path:
    if RUNS_DIR is None or not RUNS_DIR.is_dir():
        raise HTTPException(503, "RUNS_DIR is not configured")
    return RUNS_DIR


def _run_dir(run_id: str) -> Path:
    if not RUN_ID.fullmatch(run_id):
        raise HTTPException(404, "no such run")
    root = _runs_dir()
    path = (root / run_id).resolve()
    if path.parent != root or not path.is_dir():
        raise HTTPException(404, "no such run")
    return path


_CACHE: dict[Path, tuple[int, dict | None]] = {}


def _load(run_dir: Path) -> dict | None:
    """result.json for a run, re-read only when the file changes."""
    path = run_dir / "result.json"
    try:
        mtime = path.stat().st_mtime_ns
    except OSError:
        return None
    hit = _CACHE.get(path)
    if hit and hit[0] == mtime:
        return hit[1]
    try:
        data = json.loads(path.read_text())
    except (OSError, ValueError):
        data = None
    _CACHE[path] = (mtime, data)
    return data


def _steps(side: dict | None) -> list[dict]:
    return [s for s in ((side or {}).get("steps") or []) if isinstance(s, dict)]


def _verified(result: dict) -> bool:
    """A run is verified when the separate clean container ran steps and it passed (flag, or every step exit 0)."""
    verifier = result.get("verifier") or {}
    steps = _steps(verifier)
    return bool(steps) and (verifier.get("passed") is True or all(s.get("exit_code") == 0 for s in steps))


def _status(result: dict) -> str:
    # runs | runs_with_gaps | broken are current. fixed | fail come from earlier agent versions,
    # which did write the verifier's steps: judge those by the steps, not by the old word.
    raw = str(result.get("result") or "unknown")
    if raw in ("runs", "runs_with_gaps", "broken"):
        return raw
    steps = _steps(result.get("verifier"))
    if steps:
        if _verified(result):
            gaps = result.get("gaps") or (result.get("verifier") or {}).get("gaps")
            return "runs_with_gaps" if gaps else "runs"
        return "broken"
    # No verifier steps: nothing was proved. "fixed" stays unverified; "fail" is broken.
    return "broken" if raw == "fail" else raw


def _fix_kind(result: dict, has_patch: bool) -> str | None:
    attempts = (result.get("agent") or {}).get("attempts") or []
    kinds = {a.get("kind") for a in attempts if a.get("status") in ("applied", "needs_approval")}
    if "code" in kinds:
        return "code"
    if "config" in kinds:
        return "config"
    if has_patch or (result.get("agent") or {}).get("rules_fired"):
        return "config"
    return None


_ANSI = re.compile(r"\x1b\[[0-9;]*m")
_ERROR_LINE = re.compile(r"error|ERR_|failed|timed out|fatal|exit code|cannot|not found", re.I)


def _tail(step: dict) -> list[str]:
    return [_ANSI.sub("", str(x)) for x in (step.get("output_tail") or []) if str(x).strip()]


def _error_line(result: dict) -> str | None:
    """The first error line of the first agent step that failed."""
    for s in _steps(result.get("agent")):
        if s.get("exit_code") != 0:
            lines = _tail(s)
            hit = next((l for l in lines if _ERROR_LINE.search(l)), None)
            return (hit or (lines[-1] if lines else None) or "")[:240] or None
    return None


def _problems(result: dict) -> list[dict]:
    """Causes of rot that the record itself evidences: {key, evidence}."""
    out: list[dict] = []
    lines = [l for s in _steps(result.get("agent")) for l in _tail(s)]
    hit = next((l for l in lines if "ERR_PNPM_IGNORED_BUILDS" in l), None)
    if hit:
        nxt = next((l for l in lines if "Ignored build scripts" in l), None)
        extra = re.sub(r"^[\s╰▶─×]+", "", nxt).strip() if nxt else None
        out.append({"key": "toolchain", "evidence": "\n".join(x for x in (hit, extra) if x)})
    for a in (result.get("agent") or {}).get("attempts") or []:
        why = a.get("rationale") or ""
        if re.search(r"better-sqlite3|native|V8|node-gyp", why, re.I):
            out.append({"key": "runtime", "evidence": why[:700]})
            break
    clock = next((l for l in lines if re.match(r"^timed out after \d+s", l)), None)
    if clock:
        out.append({"key": "clock", "evidence": clock})
    return out


def _brief(step: dict) -> dict:
    return {"name": step.get("name"), "ok": step.get("exit_code") == 0, "duration_s": step.get("duration_s")}


def _summary(run_id: str, result: dict, patch: str | None) -> dict:
    started, ended = result.get("started"), result.get("ended")
    agent = result.get("agent") or {}
    verifier = result.get("verifier") or {}
    calls = result.get("model_calls") or []
    model_s = sum(c.get("duration_s") or 0 for c in calls)
    patch_lines = patch.splitlines() if patch else []
    return {
        "id": run_id,
        "repo": result.get("repo"),
        "sha": result.get("sha"),
        "path": result.get("path") or "",
        "type": result.get("type"),
        "status": _status(result),
        "duration_s": round(ended - started, 1) if isinstance(started, (int, float)) and isinstance(ended, (int, float)) else None,
        "model_calls": len(calls),
        "fix_kind": _fix_kind(result, bool(patch)),
        "needs_approval": bool(result.get("needs_approval")),
        "started": started,
        # What the landing page draws from, so it does not fetch every run's record.
        "verified": _verified(result),
        "gaps": result.get("gaps") or verifier.get("gaps") or [],
        "agent_steps": [_brief(s) for s in _steps(agent)],
        "verifier_steps": [_brief(s) for s in _steps(verifier)],
        "attempts": [
            {
                "kind": a.get("kind"),
                "files": a.get("files") or [],
                "result": a.get("result"),
                "status": a.get("status"),
                "confidence": a.get("confidence"),
                "rationale": (a.get("rationale") or "")[:700] or None,
            }
            for a in (agent.get("attempts") or [])
        ],
        "rules_fired": agent.get("rules_fired") or [],
        "model": next((c.get("model") for c in calls if c.get("model")), None),
        "model_seconds": round(model_s, 1) if calls else None,
        "error_line": _error_line(result),
        "problems": _problems(result),
        "patch_preview": "\n".join(patch_lines[:14]) if patch else None,
        "patch_added": sum(1 for l in patch_lines if l.startswith("+") and not l.startswith("+++")),
    }


def _checking_row(entry: Path) -> dict:
    return {"id": entry.name, "repo": None, "sha": None, "path": "", "type": None, "status": "checking",
            "duration_s": None, "model_calls": 0, "fix_kind": None, "needs_approval": False,
            "started": entry.stat().st_mtime, "verified": False, "gaps": [], "agent_steps": [],
            "verifier_steps": [], "attempts": [], "rules_fired": [], "model": None, "model_seconds": None,
            "error_line": None, "problems": [], "patch_preview": None, "patch_added": 0}


def _rows() -> list[dict]:
    root = _runs_dir()
    now = time.time()
    rows = []
    for entry in root.iterdir():
        if not RUN_ID.fullmatch(entry.name) or not entry.is_dir() or entry.resolve().parent != root:
            continue
        result = _load(entry)
        if result is not None:
            try:
                patch = (entry / "fix.patch").read_text()
            except OSError:
                patch = None
            rows.append(_summary(entry.name, result, patch))
        elif now - entry.stat().st_mtime < CHECKING_WINDOW_S:
            rows.append(_checking_row(entry))
    rows.sort(key=lambda r: r["id"], reverse=True)
    return rows


@app.get("/api/runs")
def list_runs() -> list[dict]:
    return _rows()


@app.get("/api/runs/{run_id}")
def get_run(run_id: str) -> dict:
    run_dir = _run_dir(run_id)
    result = _load(run_dir)
    if result is None:
        raise HTTPException(404, "this run has no record yet")
    patch = None
    try:
        patch = (run_dir / "fix.patch").read_text()
    except OSError:
        pass
    return {"summary": _summary(run_id, result, patch), "result": result, "fix_patch": patch}


# Agent view: the same facts as the site, in plain text. Paths are relative on purpose.
_STATUS_WORD = {"runs": "Runs", "runs_with_gaps": "Runs with gaps", "broken": "Broken", "fixed": "Fixed, unverified"}

_HOW = """## How a run is proved

1. **Fresh clone.** The agent container clones the repository at a pinned commit, picks the package manager from the lockfile, and runs install, build, test and start in order, stopping at the first failure.
2. **Diagnose.** Deterministic rules run first. A model is called only when a step failed; it proposes the least invasive fix (configuration before source code).
3. **Repair.** The fix is applied as a patch and the failed step is run again. Source-code changes are proposed and marked `needs_approval`; they are not applied on their own.
4. **Prove.** A second, separate container rebuilds from a fresh clone with the recipe and the patch only. Its steps are recorded as `verifier.steps`. The agent that wrote the fix cannot write to it.

## Status vocabulary

- `runs` (✓ Runs): the verifier ran and every step passed.
- `runs_with_gaps` (◐ Runs with gaps): the verifier passed, and the record lists `gaps` (things it could not exercise, such as a missing test script).
- `broken` (✗ Broken): a step failed and no verified fix exists.
- `checking` (◌ Checking): the run has started and has no record yet.
- `fixed` (◐ Fixed, unverified): only in records from an earlier agent version that have no verifier steps at all.

A run counts as verified only when `verified` is true: the verifier has at least one step and all steps exited 0. Nothing is claimed beyond the recorded steps; for example a verifier that only ran `install` has proved the install, not the build.
"""

_API = """## API (read-only, JSON)

- `GET /api/runs`: every run, newest first. Each item carries `id`, `repo`, `sha`, `path`, `type`, `status`, `verified`, `duration_s`, `model_calls`, `fix_kind` (`config`, `code` or null), `needs_approval`, `gaps`, `agent_steps` and `verifier_steps` (`name`, `ok`, `duration_s`), `attempts` (`kind`, `files`, `result`, `status`, `confidence`, `rationale`), `error_line`, `problems`, `patch_preview`.
- `GET /api/runs/{id}`: one run as `{summary, result, fix_patch}`. `result` is the full record: steps with commands, exit codes, durations and output tails, model calls, and attempts. `fix_patch` is a unified diff or null.
- Run ids look like `20261010T120139Z-5c3370f` (UTC start time, then the short commit).

## Pages

- `/`: the landing page. `/runs`: the gallery. `/runs/{id}`: one run with a replay and its fix diff.
- `/index.md` and `/llms.txt`: this description.
"""


def _agent_view(short: bool) -> str:
    head = (
        "# Resurgo\n\n"
        "> Resurgo fresh-clones a repository, repairs what rotted, and proves the fix in a separate clean container.\n\n"
        "Current state: a hackathon build. The GitHub App is not live; every run below was started by hand, "
        "on public repositories. There are no customers, testimonials or benchmark claims on this site.\n\n"
    )
    live = ""
    try:
        latest: dict[tuple, dict] = {}
        for r in _rows():
            if r["repo"] and r["status"] != "checking":
                latest.setdefault((r["repo"], r["path"]), r)
        if latest:
            live = "## Latest run per repository\n\n" + "\n".join(
                f"- [{r['repo']}{'/' + r['path'] if r['path'] else ''}](/runs/{r['id']}): "
                f"{_STATUS_WORD.get(r['status'], r['status'])}"
                f"{', verified' if r['verified'] else ''}"
                f"{', fix: ' + r['fix_kind'] if r['fix_kind'] else ''}"
                for r in latest.values()
            ) + "\n\n"
    except HTTPException:
        pass  # RUNS_DIR not configured: describe the system without a live list
    if short:
        return head + live + "## Links\n\n- [Full description](/index.md)\n- [Run list as JSON](/api/runs)\n"
    return head + live + _API + "\n" + _HOW


@app.get("/index.md", include_in_schema=False)
def agent_view_md() -> PlainTextResponse:
    return PlainTextResponse(_agent_view(short=False), media_type="text/markdown; charset=utf-8")


@app.get("/llms.txt", include_in_schema=False)
def agent_view_llms() -> PlainTextResponse:
    return PlainTextResponse(_agent_view(short=True), media_type="text/plain; charset=utf-8")


# The built web app, with SPA fallback. Never serve outside DIST_DIR.
@app.get("/{rest:path}", include_in_schema=False)
def web(rest: str):
    if rest.startswith("api/"):
        raise HTTPException(404)
    candidate = (DIST_DIR / rest).resolve()
    if rest and candidate.is_file() and DIST_DIR in candidate.parents:
        return FileResponse(candidate)
    index = DIST_DIR / "index.html"
    if not index.is_file():
        raise HTTPException(404, "web app is not built")
    return FileResponse(index)

