1	import { useEffect, useId, useMemo, useState, type FormEvent } from "react";
2	import { Link } from "react-router-dom";
3	import { useReducedMotion } from "motion/react";
4	import { Story } from "@/components/Story";
5	import { useRun, type RunSummary } from "@/lib/api";
6	import { statusMeta } from "@/lib/run";
7	import { readingMs, useStream } from "@/lib/stream";
8	
9	/** owner/name from "owner/name", a github.com URL, or a git remote. Null when it isn't one. */
10	export function parseRepo(input: string): string | null {
11	  let s = input.trim();
12	  if (!s) return null;
13	  s = s.replace(/^git@github\.com:/i, "").replace(/^(https?:\/\/)?(www\.)?github\.com\//i, "");
14	  s = s.replace(/[?#].*$/, "").replace(/\.git$/i, "").replace(/\/+$/, "");
15	  const [owner, name] = s.split("/");
16	  if (!owner || !name || !/^[\w.-]+$/.test(owner) || !/^[\w.-]+$/.test(name)) return null;
17	  return `${owner}/${name}`;
18	}
19	
20	const NO_LIVE = "Live checks open with the GitHub App.";
21	
22	type Asked = { nonce: number; text: string; repo: string | null; match: RunSummary | null };
23	
24	function Reply({ asked, latest, onPick }: { asked: Asked; latest: RunSummary[]; onPick: (repo: string) => void }) {
25	  const { match } = asked;
26	  const intro = match
27	    ? `Found ${match.repo} in the gallery. Its latest recorded run, at ${match.sha}: ${statusMeta(match.status).word}. Replaying that run.`
28	    : asked.repo
29	      ? `${NO_LIVE} ${asked.repo} has no recorded run yet, so there is nothing to replay.`
30	      : `That doesn't look like a public GitHub repo. Paste owner/name or a github.com link. ${NO_LIVE}`;
31	  const reduce = useReducedMotion();
32	  // Anticipation: a spinner for a beat, then the reply streams.
33	  const { shown, done, started } = useStream(intro, { restartKey: asked.nonce, delay: 450 });
34	  // Reading pause (250 ms + 30 ms a word) before the replay takes the stage.
35	  const [read, setRead] = useState(!!reduce);
36	  useEffect(() => {
37	    if (reduce || !done) return;
38	    const id = window.setTimeout(() => setRead(true), readingMs(intro));
39	    return () => window.clearTimeout(id);
40	  }, [reduce, done, intro]);
41	  const { data: detail, loading } = useRun(match && done && read ? match.id : null);
42	  return (
43	    <div className="space-y-4">
44	      <p className="settle rounded-lg border border-border bg-panel px-4 py-3">
45	        {!started && !done && <span className="text-muted-foreground">◌ Looking in the gallery…</span>}
46	        {shown}
47	        {started && !done && <span className="stream-cursor" />}
48	      </p>
49	      {match && done && read && loading && <p className="text-sm text-muted-foreground" role="status">◌ Loading the recorded run…</p>}
50	      {match && detail && <Story detail={detail} runKey={asked.nonce} label={`Replay of the recorded run for ${match.repo}`} />}
51	      {!match && done && latest.length > 0 && (
52	        <div className="settle">
53	          <p className="text-sm text-muted-foreground">These repositories have real recorded runs you can replay:</p>
54	          <ul className="mt-2 flex flex-wrap gap-2" role="list">
55	            {latest.map((r) => (
56	              <li key={r.id}>
57	                <button
58	                  type="button"
59	                  onClick={() => r.repo && onPick(r.repo)}
60	                  className="press rounded-md border border-control bg-panel px-3 py-1.5 font-mono text-sm hover:bg-muted"
61	                >
62	                  {r.repo}
63	                </button>
64	              </li>
65	            ))}
66	          </ul>
67	        </div>
68	      )}
